async (page) => {
  const started = new Date().toISOString();
  const results = [];
  const browser = page.context().browser();
  for (const [name, host] of [['resident','https://ca-resident-demo.happyriver-ace49996.uksouth.azurecontainerapps.io'],['employee','https://ca-cutover-test-demo-api.happyriver-ace49996.uksouth.azurecontainerapps.io']]) {
    for (const viewport of [{width:1365,height:900},{width:390,height:844}]) {
      const context = await browser.newContext({viewport});
      const p = await context.newPage();
      const requests = [], responses = [], consoleErrors = [], pageErrors = [];
      p.on('request', r => { const u = new URL(r.url()); if(u.origin === host) requests.push({method:r.method(),path:u.pathname + (u.searchParams.has('v') ? '?v='+u.searchParams.get('v') : '')}); });
      p.on('response', r => { const u = new URL(r.url()); if(u.origin === host) responses.push({path:u.pathname + (u.searchParams.has('v') ? '?v='+u.searchParams.get('v') : ''),status:r.status()}); });
      p.on('console', m => { if(m.type()==='error') consoleErrors.push('console error'); });
      p.on('pageerror', e => pageErrors.push(e.name));
      try {
        const health = await context.request.get(host+'/healthz',{timeout:180000});
        if(health.status()!==200) throw new Error(name+' health not200');
        const response = await p.goto(host+'/',{waitUntil:'networkidle',timeout:180000});
        if(response.status()!==200) throw new Error(name+' public not200');
        const dom = await p.evaluate(() => ({title:document.title,overflow:document.documentElement.scrollWidth>innerWidth,assets:[...document.querySelectorAll('script[src],link[rel="stylesheet"][href]')].map(n=>n.getAttribute(n.tagName==='SCRIPT'?'src':'href')),passwordInputs:document.querySelectorAll('input[type=password]').length,launchers:document.querySelectorAll('.chat-widget-launcher').length,dialogs:document.querySelectorAll('.chat-widget[role=dialog]').length,widgetRuntime:typeof window.ChatWidget?.create==='function'}));
        if(!dom.assets.length || dom.assets.some(u=>u.startsWith('/')&&!u.includes('?v='))) throw new Error(name+' unversioned public asset');
        let interaction = null;
        if(name==='resident') {
          if(dom.launchers!==1||dom.dialogs!==1||!dom.widgetRuntime) throw new Error('resident widget absent');
          const launcher = p.locator('.chat-widget-launcher');
          await launcher.click();
          const panel = p.locator('.chat-widget[role=dialog]');
          await panel.waitFor({state:'visible'});
          await panel.getByText('Chat size',{exact:true}).click();
          const dock = panel.getByRole('button',{name:'Dock to right edge',exact:true});
          await dock.click();
          const docked = await panel.evaluate(n=>({docked:n.classList.contains('chat-widget-docked'),width:n.getBoundingClientRect().width,height:n.getBoundingClientRect().height}));
          if(!docked.docked) throw new Error('dock did not open');
          await dock.click();
          await p.keyboard.press('Escape');
          if(await panel.isVisible()) throw new Error('Escape did not close');
          interaction={opened:true,dockControlPresent:true,docked:true,undocked:true,escapeClosed:true,dockedSize:docked,noSubmission:true};
        }
        const protectedResult = await context.request.get(host+(name==='resident'?'/demo/view':'/app'),{timeout:180000,maxRedirects:0});
        const protectedStatus = protectedResult.status();
        if(name==='resident' ? protectedStatus!==401 : ![401,302].includes(protectedStatus)) throw new Error(name+' unexpected protected status '+protectedStatus);
        const location = protectedResult.headers()['location'];
        const redirect = location ? new URL(location,host) : null;
        if(redirect && ![new URL(host).origin,'https://login.microsoftonline.com'].includes(redirect.origin)) throw new Error('Unexpected anonymous redirect origin');
        if(requests.some(r=>r.method!=='GET')) throw new Error('unexpected browser submission');
        if(name==='resident' && !responses.some(r=>r.path.startsWith('/chat-widget.js?v=')&&r.status===200)) throw new Error('resident JS not200');
        if(name==='resident' && !responses.some(r=>r.path.startsWith('/chat-widget.css?v=')&&r.status===200)) throw new Error('resident CSS not200');
        results.push({site:name,viewport,health:health.status(),public:response.status(),htmlCache:response.headers()['cache-control'],dom,interaction,anonymousProtected:protectedStatus,redirectOrigin:redirect?.origin||null,requests,responses,consoleErrors:consoleErrors.length,pageErrors,noSignin:true,noModel:true});
      } finally { await context.close(); }
    }
  }
  return {started,finished:new Date().toISOString(),results};
}

